_LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def column_name(index):
    """Return the spreadsheet column name for a 1-based index (1 -> 'A', 27 -> 'AA')."""
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 1:
        raise ValueError("index must be at least 1")
    chars = []
    n = index
    while n > 0:
        n, rem = divmod(n - 1, 26)
        chars.append(_LETTERS[rem])
    return "".join(reversed(chars))


def column_index(name):
    """Return the 1-based index for a spreadsheet column name; case-insensitive ASCII letters only."""
    if not name:
        raise ValueError("column name must not be empty")
    total = 0
    for ch in name:
        if not ("A" <= ch <= "Z" or "a" <= ch <= "z"):
            raise ValueError("invalid character in column name: %r" % (ch,))
        total = total * 26 + (ord(ch.upper()) - ord("A") + 1)
    return total
